//! Core color type and conversion routines.

#[derive(Clone, Copy, Debug)]
pub struct Color {
    pub r: f64, // linear 0..1 (gamma encoded sRGB in 0..1 range, really)
    pub g: f64,
    pub b: f64,
    pub alpha: f64,
}

impl Color {
    pub fn from_rgb_u8(r: u8, g: u8, b: u8) -> Color {
        Color {
            r: r as f64 / 255.0,
            g: g as f64 / 255.0,
            b: b as f64 / 255.0,
            alpha: 1.0,
        }
    }

    pub fn from_rgba(r: f64, g: f64, b: f64, a: f64) -> Color {
        Color {
            r: r.clamp(0.0, 1.0),
            g: g.clamp(0.0, 1.0),
            b: b.clamp(0.0, 1.0),
            alpha: a.clamp(0.0, 1.0),
        }
    }

    pub fn to_rgb_u8(&self) -> (u8, u8, u8) {
        (
            (self.r * 255.0).round().clamp(0.0, 255.0) as u8,
            (self.g * 255.0).round().clamp(0.0, 255.0) as u8,
            (self.b * 255.0).round().clamp(0.0, 255.0) as u8,
        )
    }

    pub fn alpha_u8(&self) -> u8 {
        (self.alpha * 255.0).round().clamp(0.0, 255.0) as u8
    }

    // === HSL =================================================
    pub fn to_hsla(&self) -> (f64, f64, f64, f64) {
        let max = self.r.max(self.g).max(self.b);
        let min = self.r.min(self.g).min(self.b);
        let l = (max + min) / 2.0;
        let (h, s) = if (max - min).abs() < 1e-12 {
            (0.0, 0.0)
        } else {
            let d = max - min;
            let s = if l > 0.5 {
                d / (2.0 - max - min)
            } else {
                d / (max + min)
            };
            let h = if (max - self.r).abs() < 1e-12 {
                ((self.g - self.b) / d + if self.g < self.b { 6.0 } else { 0.0 }) * 60.0
            } else if (max - self.g).abs() < 1e-12 {
                ((self.b - self.r) / d + 2.0) * 60.0
            } else {
                ((self.r - self.g) / d + 4.0) * 60.0
            };
            (h, s)
        };
        (h, s, l, self.alpha)
    }

    pub fn from_hsla(h: f64, s: f64, l: f64, a: f64) -> Color {
        let h = ((h % 360.0) + 360.0) % 360.0;
        let s = s.clamp(0.0, 1.0);
        let l = l.clamp(0.0, 1.0);
        let c = (1.0 - (2.0 * l - 1.0).abs()) * s;
        let hp = h / 60.0;
        let x = c * (1.0 - (hp % 2.0 - 1.0).abs());
        let (r1, g1, b1) = if hp < 1.0 {
            (c, x, 0.0)
        } else if hp < 2.0 {
            (x, c, 0.0)
        } else if hp < 3.0 {
            (0.0, c, x)
        } else if hp < 4.0 {
            (0.0, x, c)
        } else if hp < 5.0 {
            (x, 0.0, c)
        } else {
            (c, 0.0, x)
        };
        let m = l - c / 2.0;
        Color {
            r: (r1 + m).clamp(0.0, 1.0),
            g: (g1 + m).clamp(0.0, 1.0),
            b: (b1 + m).clamp(0.0, 1.0),
            alpha: a.clamp(0.0, 1.0),
        }
    }

    // === HSV =================================================
    pub fn to_hsva(&self) -> (f64, f64, f64, f64) {
        let max = self.r.max(self.g).max(self.b);
        let min = self.r.min(self.g).min(self.b);
        let v = max;
        let d = max - min;
        let s = if max == 0.0 { 0.0 } else { d / max };
        let h = if d.abs() < 1e-12 {
            0.0
        } else if (max - self.r).abs() < 1e-12 {
            ((self.g - self.b) / d + if self.g < self.b { 6.0 } else { 0.0 }) * 60.0
        } else if (max - self.g).abs() < 1e-12 {
            ((self.b - self.r) / d + 2.0) * 60.0
        } else {
            ((self.r - self.g) / d + 4.0) * 60.0
        };
        (h, s, v, self.alpha)
    }

    // === Lab (CIELAB, D65 white point) =======================
    // sRGB decode
    fn srgb_decode(u: f64) -> f64 {
        if u <= 0.04045 {
            u / 12.92
        } else {
            ((u + 0.055) / 1.055).powf(2.4)
        }
    }
    fn srgb_encode(u: f64) -> f64 {
        if u <= 0.0031308 {
            12.92 * u
        } else {
            1.055 * u.powf(1.0 / 2.4) - 0.055
        }
    }

    pub fn to_xyz(&self) -> (f64, f64, f64) {
        let r = Self::srgb_decode(self.r);
        let g = Self::srgb_decode(self.g);
        let b = Self::srgb_decode(self.b);
        // sRGB to XYZ matrix (D65)
        let x = 0.4124564 * r + 0.3575761 * g + 0.1804375 * b;
        let y = 0.2126729 * r + 0.7151522 * g + 0.0721750 * b;
        let z = 0.0193339 * r + 0.1191920 * g + 0.9503041 * b;
        (x, y, z)
    }

    pub fn from_xyz(x: f64, y: f64, z: f64, alpha: f64) -> Color {
        let r = 3.2404542 * x - 1.5371385 * y - 0.4985314 * z;
        let g = -0.9692660 * x + 1.8760108 * y + 0.0415560 * z;
        let b = 0.0556434 * x - 0.2040259 * y + 1.0572252 * z;
        Color {
            r: Self::srgb_encode(r).clamp(0.0, 1.0),
            g: Self::srgb_encode(g).clamp(0.0, 1.0),
            b: Self::srgb_encode(b).clamp(0.0, 1.0),
            alpha: alpha.clamp(0.0, 1.0),
        }
    }

    // D65 reference white point
    const XN: f64 = 0.95047;
    const YN: f64 = 1.0;
    const ZN: f64 = 1.08883;

    fn lab_f(t: f64) -> f64 {
        let d = 6.0 / 29.0;
        if t > d * d * d {
            t.cbrt()
        } else {
            t / (3.0 * d * d) + 4.0 / 29.0
        }
    }

    fn lab_f_inv(t: f64) -> f64 {
        let d = 6.0 / 29.0;
        if t > d {
            t * t * t
        } else {
            3.0 * d * d * (t - 4.0 / 29.0)
        }
    }

    pub fn to_laba(&self) -> (f64, f64, f64, f64) {
        let (x, y, z) = self.to_xyz();
        let fx = Self::lab_f(x / Self::XN);
        let fy = Self::lab_f(y / Self::YN);
        let fz = Self::lab_f(z / Self::ZN);
        let l = 116.0 * fy - 16.0;
        let a = 500.0 * (fx - fy);
        let b = 200.0 * (fy - fz);
        (l, a, b, self.alpha)
    }

    pub fn from_laba(l: f64, a: f64, b: f64, alpha: f64) -> Color {
        let fy = (l + 16.0) / 116.0;
        let fx = a / 500.0 + fy;
        let fz = fy - b / 200.0;
        let x = Self::XN * Self::lab_f_inv(fx);
        let y = Self::YN * Self::lab_f_inv(fy);
        let z = Self::ZN * Self::lab_f_inv(fz);
        Self::from_xyz(x, y, z, alpha)
    }

    pub fn to_lcha(&self) -> (f64, f64, f64, f64) {
        let (l, a, b, alpha) = self.to_laba();
        let c = (a * a + b * b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h < 0.0 {
            h += 360.0;
        }
        (l, c, h, alpha)
    }

    pub fn from_lcha(l: f64, c: f64, h: f64, alpha: f64) -> Color {
        let a = c * h.to_radians().cos();
        let b = c * h.to_radians().sin();
        Self::from_laba(l, a, b, alpha)
    }

    // === OkLab ============================================
    pub fn to_oklaba(&self) -> (f64, f64, f64, f64) {
        let r = Self::srgb_decode(self.r);
        let g = Self::srgb_decode(self.g);
        let b = Self::srgb_decode(self.b);
        let l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b;
        let m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b;
        let s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b;
        let l_ = l.cbrt();
        let m_ = m.cbrt();
        let s_ = s.cbrt();
        let l_ok = 0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_;
        let a_ok = 1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_;
        let b_ok = 0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_;
        (l_ok, a_ok, b_ok, self.alpha)
    }

    pub fn from_oklaba(l_ok: f64, a_ok: f64, b_ok: f64, alpha: f64) -> Color {
        let l_ = l_ok + 0.3963377774 * a_ok + 0.2158037573 * b_ok;
        let m_ = l_ok - 0.1055613458 * a_ok - 0.0638541728 * b_ok;
        let s_ = l_ok - 0.0894841775 * a_ok - 1.2914855480 * b_ok;
        let l = l_ * l_ * l_;
        let m = m_ * m_ * m_;
        let s = s_ * s_ * s_;
        let r = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
        let g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
        let b = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;
        Color {
            r: Self::srgb_encode(r).clamp(0.0, 1.0),
            g: Self::srgb_encode(g).clamp(0.0, 1.0),
            b: Self::srgb_encode(b).clamp(0.0, 1.0),
            alpha: alpha.clamp(0.0, 1.0),
        }
    }

    pub fn to_oklcha(&self) -> (f64, f64, f64, f64) {
        let (l, a, b, alpha) = self.to_oklaba();
        let c = (a * a + b * b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h < 0.0 {
            h += 360.0;
        }
        (l, c, h, alpha)
    }

    pub fn from_oklcha(l: f64, c: f64, h: f64, alpha: f64) -> Color {
        let a = c * h.to_radians().cos();
        let b = c * h.to_radians().sin();
        Self::from_oklaba(l, a, b, alpha)
    }

    // === Brightness and luminance ============================
    // Luminance: WCAG relative luminance (linear Y)
    pub fn luminance(&self) -> f64 {
        let r = Self::srgb_decode(self.r);
        let g = Self::srgb_decode(self.g);
        let b = Self::srgb_decode(self.b);
        0.2126 * r + 0.7152 * g + 0.0722 * b
    }
    // Brightness: perceived brightness, rec601-style
    pub fn brightness(&self) -> f64 {
        0.299 * self.r + 0.587 * self.g + 0.114 * self.b
    }

    // === CMYK ================================================
    pub fn to_cmyk(&self) -> (f64, f64, f64, f64) {
        let k = 1.0 - self.r.max(self.g).max(self.b);
        if k >= 1.0 - 1e-12 {
            (0.0, 0.0, 0.0, 1.0)
        } else {
            let c = (1.0 - self.r - k) / (1.0 - k);
            let m = (1.0 - self.g - k) / (1.0 - k);
            let y = (1.0 - self.b - k) / (1.0 - k);
            (c, m, y, k)
        }
    }

    // === ANSI 8-bit =========================================
    pub fn to_ansi_8bit(&self) -> u8 {
        // Find nearest ANSI color (16-231 in 6x6x6 cube, 232-255 grayscale, plus 0-15 system)
        let (r, g, b) = self.to_rgb_u8();
        let rgb = (r as f64, g as f64, b as f64);

        let mut best = 0u8;
        let mut best_d = f64::INFINITY;
        for i in 0..=255u16 {
            let (pr, pg, pb) = ansi_256_to_rgb(i as u8);
            let dr = rgb.0 - pr as f64;
            let dg = rgb.1 - pg as f64;
            let db = rgb.2 - pb as f64;
            let d = dr * dr + dg * dg + db * db;
            if d < best_d {
                best_d = d;
                best = i as u8;
            }
        }
        best
    }
}

pub fn ansi_256_to_rgb(idx: u8) -> (u8, u8, u8) {
    // Standard xterm 256 color palette
    match idx {
        0 => (0, 0, 0),
        1 => (128, 0, 0),
        2 => (0, 128, 0),
        3 => (128, 128, 0),
        4 => (0, 0, 128),
        5 => (128, 0, 128),
        6 => (0, 128, 128),
        7 => (192, 192, 192),
        8 => (128, 128, 128),
        9 => (255, 0, 0),
        10 => (0, 255, 0),
        11 => (255, 255, 0),
        12 => (0, 0, 255),
        13 => (255, 0, 255),
        14 => (0, 255, 255),
        15 => (255, 255, 255),
        16..=231 => {
            let v = idx - 16;
            let r = v / 36;
            let g = (v / 6) % 6;
            let b = v % 6;
            let to_6 = |c: u8| -> u8 {
                if c == 0 {
                    0
                } else {
                    55 + 40 * c
                }
            };
            (to_6(r), to_6(g), to_6(b))
        }
        232..=255 => {
            let v = idx - 232;
            let g = 8 + 10 * v;
            (g, g, g)
        }
    }
}
