        let l_ = l_ok + 0.3963377774 * a_ok + 0.2158037573 * b_ok;
        let m_ = l_ok - 0.1055613458 * a_ok - 0.0638541728 * b_ok;
        let s_ = l_ok - 0.0894841775 * a_ok - 1.2914855480 * b_ok;
        let l = l_ * l_ * l_;
        let m = m_ * m_ * m_;
        let s = s_ * s_ * s_;
        let r = 4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s;
        let g = -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s;
        let b = -0.0041960863 * l - 0.7034186147 * m + 1.7076147010 * s;
        Color {
            r: Self::srgb_encode(r).clamp(0.0, 1.0),
            g: Self::srgb_encode(g).clamp(0.0, 1.0),
            b: Self::srgb_encode(b).clamp(0.0, 1.0),
            alpha: alpha.clamp(0.0, 1.0),
        }
    }

    pub fn to_oklcha(&self) -> (f64, f64, f64, f64) {
        let (l, a, b, alpha) = self.to_oklaba();
        let c = (a * a + b * b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h < 0.0 {
            h += 360.0;
        }
        (l, c, h, alpha)
    }

    pub fn from_oklcha(l: f64, c: f64, h: f64, alpha: f64) -> Color {
        let a = c * h.to_radians().cos();
        let b = c * h.to_radians().sin();
        Self::from_oklaba(l, a, b, alpha)
    }

    // === Brightness and luminance ============================
    // Luminance: WCAG relative luminance (linear Y)
    pub fn luminance(&self) -> f64 {
        let r = Self::srgb_decode(self.r);
        let g = Self::srgb_decode(self.g);
        let b = Self::srgb_decode(self.b);
        0.2126 * r + 0.7152 * g + 0.0722 * b
    }
    // Brightness: perceived brightness, rec601-style
    pub fn brightness(&self) -> f64 {
        0.299 * self.r + 0.587 * self.g + 0.114 * self.b
    }

    // === CMYK ================================================
    pub fn to_cmyk(&self) -> (f64, f64, f64, f64) {
        let k = 1.0 - self.r.max(self.g).max(self.b);
        if k >= 1.0 - 1e-12 {
            (0.0, 0.0, 0.0, 1.0)
        } else {
            let c = (1.0 - self.r - k) / (1.0 - k);
            let m = (1.0 - self.g - k) / (1.0 - k);
            let y = (1.0 - self.b - k) / (1.0 - k);
            (c, m, y, k)
        }
    }

    // === ANSI 8-bit =========================================
    pub fn to_ansi_8bit(&self) -> u8 {
        // Find nearest ANSI color (16-231 in 6x6x6 cube, 232-255 grayscale, plus 0-15 system)
        let (r, g, b) = self.to_rgb_u8();
        let rgb = (r as f64, g as f64, b as f64);

        let mut best = 0u8;
        let mut best_d = f64::INFINITY;
        for i in 0..=255u16 {
            let (pr, pg, pb) = ansi_256_to_rgb(i as u8);
            let dr = rgb.0 - pr as f64;
            let dg = rgb.1 - pg as f64;
            let db = rgb.2 - pb as f64;
            let d = dr * dr + dg * dg + db * db;
            if d < best_d {
                best_d = d;
                best = i as u8;
            }
        }
        best
    }
}

pub fn ansi_256_to_rgb(idx: u8) -> (u8, u8, u8) {
    // Standard xterm 256 color palette
    match idx {
        0 => (0, 0, 0),
        1 => (128, 0, 0),
        2 => (0, 128, 0),
        3 => (128, 128, 0),
        4 => (0, 0, 128),
        5 => (128, 0, 128),
        6 => (0, 128, 128),
        7 => (192, 192, 192),
        8 => (128, 128, 128),
        9 => (255, 0, 0),
        10 => (0, 255, 0),
        11 => (255, 255, 0),
        12 => (0, 0, 255),
        13 => (255, 0, 255),
        14 => (0, 255, 255),
        15 => (255, 255, 255),
        16..=231 => {
            let v = idx - 16;
            let r = v / 36;
            let g = (v / 6) % 6;
            let b = v % 6;
            let to_6 = |c: u8| -> u8 {
                if c == 0 {
                    0
                } else {
                    55 + 40 * c
                }
            };
            (to_6(r), to_6(g), to_6(b))
        }
        232..=255 => {
            let v = idx - 232;
            let g = 8 + 10 * v;
            (g, g, g)
        }
    }
}
