            let to_6 = |c: u8| -> u8 {
                if c == 0 {
                    0
                } else {
                    55 + 40 * c
                }
            };
            (to_6(r), to_6(g), to_6(b))
        }
        232..=255 => {
            let v = idx - 232;
            let g = 8 + 10 * v;
            (g, g, g)
        }
    }
}
