//! Parse color strings into Color values.

use crate::color::Color;
use crate::named::get_rgb_by_name;

pub fn parse_color(input: &str) -> Option<Color> {
    let s = input.trim();
    if s.is_empty() {
        return None;
    }

    // 1. Named colors (case-insensitive)
    if let Some((r, g, b)) = get_rgb_by_name(s) {
        return Some(Color::from_rgb_u8(r, g, b));
    }

    // 2. Hex with optional leading '#'
    let hex_candidate = s.strip_prefix('#').unwrap_or(s);
    if let Some(c) = parse_hex(hex_candidate) {
        return Some(c);
    }

    // 3. Functional notation: rgb(...), rgba(...), hsl(...), hsla(...), gray(...)
    if let Some(c) = parse_function(s) {
        return Some(c);
    }

    // 4. Comma-separated r, g, b
    if let Some(c) = parse_csv(s) {
        return Some(c);
    }

    None
}

fn parse_hex(s: &str) -> Option<Color> {
    // Must consist entirely of hex digits
    if !s.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    match s.len() {
        3 => {
            let r = u8::from_str_radix(&s[0..1], 16).ok()?;
            let g = u8::from_str_radix(&s[1..2], 16).ok()?;
            let b = u8::from_str_radix(&s[2..3], 16).ok()?;
            Some(Color::from_rgb_u8(r * 17, g * 17, b * 17))
        }
        4 => {
            let r = u8::from_str_radix(&s[0..1], 16).ok()?;
            let g = u8::from_str_radix(&s[1..2], 16).ok()?;
            let b = u8::from_str_radix(&s[2..3], 16).ok()?;
            let a = u8::from_str_radix(&s[3..4], 16).ok()?;
            let r = r * 17;
            let g = g * 17;
            let b = b * 17;
            let a = a * 17;
            Some(Color {
                r: r as f64 / 255.0,
                g: g as f64 / 255.0,
                b: b as f64 / 255.0,
                alpha: a as f64 / 255.0,
            })
        }
        6 => {
            let r = u8::from_str_radix(&s[0..2], 16).ok()?;
            let g = u8::from_str_radix(&s[2..4], 16).ok()?;
            let b = u8::from_str_radix(&s[4..6], 16).ok()?;
            Some(Color::from_rgb_u8(r, g, b))
        }
        8 => {
            let r = u8::from_str_radix(&s[0..2], 16).ok()?;
            let g = u8::from_str_radix(&s[2..4], 16).ok()?;
            let b = u8::from_str_radix(&s[4..6], 16).ok()?;
            let a = u8::from_str_radix(&s[6..8], 16).ok()?;
            Some(Color {
                r: r as f64 / 255.0,
                g: g as f64 / 255.0,
                b: b as f64 / 255.0,
                alpha: a as f64 / 255.0,
            })
        }
        _ => None,
    }
}

fn parse_function(s: &str) -> Option<Color> {
    let open = s.find('(')?;
    if !s.ends_with(')') {
        return None;
    }
    let name = s[..open].trim().to_ascii_lowercase();
    let args = &s[open + 1..s.len() - 1];
    let parts: Vec<&str> = args.split(',').map(|p| p.trim()).collect();

    match name.as_str() {
        "rgb" | "rgba" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            // Check if all 3 color channels are percentages or none are
            let any_pct = parts[0].ends_with('%')
                || parts[1].ends_with('%')
                || parts[2].ends_with('%');
            let all_pct = parts[0].ends_with('%')
                && parts[1].ends_with('%')
                && parts[2].ends_with('%');
            if any_pct && !all_pct {
                return None;
            }
            let r = parse_num_or_percent(parts[0], 255.0, all_pct)?;
            let g = parse_num_or_percent(parts[1], 255.0, all_pct)?;
            let b = parse_num_or_percent(parts[2], 255.0, all_pct)?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color {
                r: (r / 255.0).clamp(0.0, 1.0),
                g: (g / 255.0).clamp(0.0, 1.0),
                b: (b / 255.0).clamp(0.0, 1.0),
                alpha: alpha.clamp(0.0, 1.0),
            })
        }
        "hsl" | "hsla" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            let h = parse_hue(parts[0])?;
            let s = parse_percentage(parts[1])?;
            let l = parse_percentage(parts[2])?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color::from_hsla(h, s, l, alpha))
        }
        "hsv" | "hsva" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            let h = parse_hue(parts[0])?;
            let s = parse_percentage(parts[1])?;
            let v = parse_percentage(parts[2])?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            // Convert HSV to RGB
            Some(hsv_to_color(h, s, v, alpha))
        }
        "gray" => {
            if parts.len() != 1 {
                return None;
            }
            let l = parse_gray_amount(parts[0])?;
            Some(Color::from_rgb_u8(
                (l * 255.0).round() as u8,
                (l * 255.0).round() as u8,
                (l * 255.0).round() as u8,
            ))
        }
        _ => None,
    }
}

fn parse_csv(s: &str) -> Option<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() != 3 {
        return None;
    }
    let r: f64 = parts[0].parse().ok()?;
    let g: f64 = parts[1].parse().ok()?;
    let b: f64 = parts[2].parse().ok()?;
    Some(Color {
        r: (r / 255.0).clamp(0.0, 1.0),
        g: (g / 255.0).clamp(0.0, 1.0),
        b: (b / 255.0).clamp(0.0, 1.0),
        alpha: 1.0,
    })
}

fn parse_num_or_percent(s: &str, max: f64, is_pct: bool) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        if !is_pct {
            return None;
        }
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0) * max)
    } else {
        if is_pct {
            return None;
        }
        let v: f64 = s.parse().ok()?;
        Some(v)
    }
}

fn parse_percentage(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v / 100.0)
    }
}

fn parse_alpha(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0).clamp(0.0, 1.0))
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v.clamp(0.0, 1.0))
    }
}

fn parse_hue(s: &str) -> Option<f64> {
    let s = if let Some(rest) = s.strip_suffix("deg") {
        rest.trim()
    } else if let Some(rest) = s.strip_suffix("rad") {
        let v: f64 = rest.trim().parse().ok()?;
        return Some(v.to_degrees());
    } else {
        s
    };
    s.parse().ok()
}

fn parse_gray_amount(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0).clamp(0.0, 1.0))
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v.clamp(0.0, 1.0))
    }
}

