    let open = s.find('(')?;
    if !s.ends_with(')') {
        return None;
    }
    let name = s[..open].trim().to_ascii_lowercase();
    let args = &s[open + 1..s.len() - 1];
    let parts: Vec<&str> = args.split(',').map(|p| p.trim()).collect();

    match name.as_str() {
        "rgb" | "rgba" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            // Check if all 3 color channels are percentages or none are
            let any_pct = parts[0].ends_with('%')
                || parts[1].ends_with('%')
                || parts[2].ends_with('%');
            let all_pct = parts[0].ends_with('%')
                && parts[1].ends_with('%')
                && parts[2].ends_with('%');
            if any_pct && !all_pct {
                return None;
            }
            let r = parse_num_or_percent(parts[0], 255.0, all_pct)?;
            let g = parse_num_or_percent(parts[1], 255.0, all_pct)?;
            let b = parse_num_or_percent(parts[2], 255.0, all_pct)?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color {
                r: (r / 255.0).clamp(0.0, 1.0),
                g: (g / 255.0).clamp(0.0, 1.0),
                b: (b / 255.0).clamp(0.0, 1.0),
                alpha: alpha.clamp(0.0, 1.0),
            })
        }
        "hsl" | "hsla" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            let h = parse_hue(parts[0])?;
            let s = parse_percentage(parts[1])?;
            let l = parse_percentage(parts[2])?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color::from_hsla(h, s, l, alpha))
        }
        "hsv" | "hsva" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            let h = parse_hue(parts[0])?;
            let s = parse_percentage(parts[1])?;
            let v = parse_percentage(parts[2])?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            // Convert HSV to RGB
            Some(hsv_to_color(h, s, v, alpha))
        }
        "gray" => {
            if parts.len() != 1 {
                return None;
            }
            let l = parse_gray_amount(parts[0])?;
            Some(Color::from_rgb_u8(
                (l * 255.0).round() as u8,
                (l * 255.0).round() as u8,
                (l * 255.0).round() as u8,
            ))
        }
        _ => None,
    }
}

fn parse_csv(s: &str) -> Option<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() != 3 {
        return None;
    }
    let r: f64 = parts[0].parse().ok()?;
    let g: f64 = parts[1].parse().ok()?;
    let b: f64 = parts[2].parse().ok()?;
    Some(Color {
        r: (r / 255.0).clamp(0.0, 1.0),
        g: (g / 255.0).clamp(0.0, 1.0),
        b: (b / 255.0).clamp(0.0, 1.0),
        alpha: 1.0,
    })
}

fn parse_num_or_percent(s: &str, max: f64, is_pct: bool) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        if !is_pct {
            return None;
        }
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0) * max)
    } else {
        if is_pct {
            return None;
        }
        let v: f64 = s.parse().ok()?;
        Some(v)
    }
}

fn parse_percentage(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v / 100.0)
    }
}

fn parse_alpha(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0).clamp(0.0, 1.0))
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v.clamp(0.0, 1.0))
    }
}

fn parse_hue(s: &str) -> Option<f64> {
    let s = if let Some(rest) = s.strip_suffix("deg") {
        rest.trim()
    } else if let Some(rest) = s.strip_suffix("rad") {
        let v: f64 = rest.trim().parse().ok()?;
        return Some(v.to_degrees());
    } else {
        s
    };
    s.parse().ok()
}

fn parse_gray_amount(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0).clamp(0.0, 1.0))
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v.clamp(0.0, 1.0))
    }
}

fn hsv_to_color(h: f64, s: f64, v: f64, alpha: f64) -> Color {
    let h = ((h % 360.0) + 360.0) % 360.0;
    let c = v * s;
    let hp = h / 60.0;
    let x = c * (1.0 - ((hp % 2.0) - 1.0).abs());
    let (r1, g1, b1) = if hp < 1.0 {
        (c, x, 0.0)
    } else if hp < 2.0 {
        (x, c, 0.0)
    } else if hp < 3.0 {
        (0.0, c, x)
    } else if hp < 4.0 {
        (0.0, x, c)
    } else if hp < 5.0 {
        (x, 0.0, c)
    } else {
        (c, 0.0, x)
    };
    let m = v - c;
    Color {
        r: (r1 + m).clamp(0.0, 1.0),
        g: (g1 + m).clamp(0.0, 1.0),
        b: (b1 + m).clamp(0.0, 1.0),
        alpha: alpha.clamp(0.0, 1.0),
    }
}
