pub fn format_rgb(c: &Color) -> String {
    let (r, g, b) = c.to_rgb_u8();
    if c.alpha >= 1.0 - 1e-12 {
        format!("rgb({}, {}, {})", r, g, b)
    } else {
        format!("rgba({}, {}, {}, {})", r, g, b, format_alpha(c.alpha))
    }
}

pub fn format_rgb_float(c: &Color) -> String {
    if c.alpha >= 1.0 - 1e-12 {
        format!("rgb({:.3}, {:.3}, {:.3})", c.r, c.g, c.b)
    } else {
        format!(
            "rgb({:.3}, {:.3}, {:.3}, {})",
            c.r,
            c.g,
            c.b,
            format_alpha(c.alpha)
        )
    }
}

pub fn format_hsl(c: &Color) -> String {
    let (h, s, l, _) = c.to_hsla();
    if c.alpha >= 1.0 - 1e-12 {
        format!(
            "hsl({}, {:.1}%, {:.1}%)",
            h.round() as i32,
            s * 100.0,
            l * 100.0
        )
    } else {
        format!(
            "hsla({}, {:.1}%, {:.1}%, {})",
            h.round() as i32,
            s * 100.0,
            l * 100.0,
            format_alpha(c.alpha)
        )
    }
}

