    let (h, s, l, _) = c.to_hsla();
    if c.alpha >= 1.0 - 1e-12 {
        format!(
            "hsl({},{:.1}%,{:.1}%)",
            h.round() as i32,
            s * 100.0,
            l * 100.0
        )
    } else {
        format!(
            "hsla({},{:.1}%,{:.1}%,{})",
            h.round() as i32,
