    let (l, a, b, _) = c.to_laba();
    format!("Lab({:.0}, {:.0}, {:.0})", l, a, b)
}

pub fn format_oklab(c: &Color) -> String {
    let (l, a, b, _) = c.to_oklaba();
    format!("OkLab({:.4}, {:.4}, {:.4})", l, a, b)
}

pub fn format_cmyk(c: &Color) -> String {
    let (cy, m, y, k) = c.to_cmyk();
    format!(
        "cmyk({:.0}, {:.0}, {:.0}, {:.0})",
        cy * 100.0,
        m * 100.0,
        y * 100.0,
        k * 100.0
    )
}

pub fn format_name(c: &Color) -> String {
    // Return closest named color (Euclidean in RGB)
    let (r, g, b) = c.to_rgb_u8();
    let mut best = "";
    let mut best_d = i64::MAX;
    for (n, nr, ng, nb) in NAMED_COLORS {
        if *n == "grey"
            || *n == "darkgrey"
            || *n == "lightgrey"
            || *n == "darkslategrey"
            || *n == "lightslategrey"
            || *n == "dimgrey"
            || *n == "slategrey"
            || *n == "cyan"
            || *n == "magenta"
        {
            continue;
        }
        let dr = r as i64 - *nr as i64;
        let dg = g as i64 - *ng as i64;
        let db = b as i64 - *nb as i64;
        let d = dr * dr + dg * dg + db * db;
        if d < best_d {
            best_d = d;
            best = n;
        }
    }
    best.to_string()
}

pub fn format_alpha(a: f64) -> String {
    // formatted with no more than 3 decimal digits, trimmed trailing zeros
    let s = format!("{:.3}", a);
    // Trim trailing zeros but keep at least one digit after '.'
    let mut t: &str = s.trim_end_matches('0');
    t = t.trim_end_matches('.');
    if t.is_empty() {
        "0".to_string()
    } else if !t.contains('.') {
        format!("{}", t)
    } else {
        t.to_string()
    }
}

