    format!("{:.3}", c.luminance())
}

pub fn format_brightness(c: &Color) -> String {
    format!("{:.3}", c.brightness())
}

pub fn format_ansi_8bit_value(c: &Color) -> String {
    format!("{}", c.to_ansi_8bit())
}

pub fn format_ansi_8bit(c: &Color) -> String {
    format!("\\x1b[38;5;{}m", c.to_ansi_8bit())
}

pub fn format_ansi_24bit(c: &Color) -> String {
    let (r, g, b) = c.to_rgb_u8();
    format!("\\x1b[38;2;{};{};{}m", r, g, b)
}

pub fn format_ansi_8bit_escape(c: &Color) -> String {
    format!("\u{1b}[38;5;{}m", c.to_ansi_8bit())
}

pub fn format_ansi_24bit_escape(c: &Color) -> String {
    let (r, g, b) = c.to_rgb_u8();
    format!("\u{1b}[38;2;{};{};{}m", r, g, b)
}
