//! Very small argument-parsing helpers.

use std::collections::VecDeque;

#[derive(Debug, Clone)]
pub enum ArgError {
    Unknown(String),
    InvalidValue { name: String, value: String, possible: Vec<String> },
    MissingValue(String),
    MissingRequired(String),
    UnrecognizedSubcommand(String),
}

pub struct ArgQueue {
    args: VecDeque<String>,
}

impl ArgQueue {
    pub fn new<I: IntoIterator<Item = String>>(it: I) -> Self {
        Self {
            args: it.into_iter().collect(),
        }
    }

    pub fn peek(&self) -> Option<&str> {
        self.args.front().map(|s| s.as_str())
    }

    pub fn pop(&mut self) -> Option<String> {
        self.args.pop_front()
    }

    pub fn push_front(&mut self, s: String) {
        self.args.push_front(s);
    }

    pub fn is_empty(&self) -> bool {
        self.args.is_empty()
    }
}
