cat > /workspace/src/main.rs <<'EOF'
mod args;
mod color;
mod format;
mod help_strings;
mod named;
mod parser;
mod subcommands;

use std::io::{self, Read, Write};
use std::process::ExitCode;

fn main() -> ExitCode {
    let raw: Vec<String> = std::env::args().skip(1).collect();
    match run(raw) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            match e {
                AppError::Exit(code) => ExitCode::from(code),
                AppError::Parse(msg) => {
                    eprintln!("[pastel error]: {}", msg);
                    ExitCode::from(1)
                }
                AppError::Usage(msg) => {
                    eprintln!("{}", msg);
                    ExitCode::from(2)
                }
            }
        }
    }
}

#[derive(Debug)]
pub enum AppError {
    Exit(u8),
    Parse(String),
    Usage(String),
}

impl From<String> for AppError {
    fn from(s: String) -> Self {
        AppError::Parse(s)
    }
}

fn usage_err<T, S: AsRef<str>>(msg: S) -> Result<T, AppError> {
    Err(AppError::Usage(msg.as_ref().to_string()))
}

fn parse_err<T, S: AsRef<str>>(msg: S) -> Result<T, AppError> {
    Err(AppError::Parse(msg.as_ref().to_string()))
}

fn run(raw: Vec<String>) -> Result<(), AppError> {
    // Check for --help, --version, and global options first.
    let mut raw = raw;

    // Pre-scan: if any arg is --help or -h before any subcommand, show help.
    // (But after a subcommand, --help shows the subcommand help.)
    let mut args: Vec<String> = Vec::new();
    let mut iter = raw.drain(..).peekable();
    let mut color_mode: Option<String> = None;
    let mut _color_picker: Option<String> = None;
    let mut force_color = false;

    // Parse global options up to the first subcommand (positional).
    while let Some(a) = iter.next() {
        if a == "--help" || a == "-h" {
            print!("{}", help_strings::MAIN_HELP_LONG);
            return Ok(());
        }
        if a == "--version" || a == "-V" {
            println!("pastel 0.11.0");
            return Ok(());
        }
        if a == "--force-color" || a == "-f" {
            force_color = true;
            continue;
        }
        if a == "--color-mode" || a == "-m" {
            let v = iter
                .next()
                .ok_or_else(|| AppError::Usage("missing value for --color-mode".into()))?;
            validate_color_mode(&v)?;
            color_mode = Some(v);
            continue;
        }
        if let Some(v) = a.strip_prefix("--color-mode=") {
            validate_color_mode(v)?;
            color_mode = Some(v.to_string());
            continue;
        }
        if a == "--color-picker" {
            let v = iter
                .next()
                .ok_or_else(|| AppError::Usage("missing value for --color-picker".into()))?;
            validate_color_picker(&v)?;
            _color_picker = Some(v);
            continue;
        }
        if let Some(v) = a.strip_prefix("--color-picker=") {
            validate_color_picker(v)?;
            _color_picker = Some(v.to_string());
            continue;
        }
        // Keep everything else as remaining
        args.push(a);
        args.extend(iter);
        break;
    }

    let _ = force_color;
    let _ = color_mode;

    if args.is_empty() {
        print!("{}", help_strings::MAIN_HELP_LONG);
        return Ok(());
    }

    // The first remaining arg should be a subcommand.
    let cmd = args.remove(0);
    match cmd.as_str() {
        "help" => {
            if args.is_empty() {
                print!("{}", help_strings::MAIN_HELP_LONG);
                return Ok(());
            }
            let sub = args.remove(0);
            print_subcommand_help(&sub, true)
        }
        "color" => subcommands::color::run(args),
        "colorblind" => subcommands::colorblind::run(args),
        "colorcheck" => subcommands::colorcheck::run(args),
        "complement" => subcommands::transform::run_complement(args),
        "darken" => subcommands::transform::run_darken(args),
        "desaturate" => subcommands::transform::run_desaturate(args),
        "distinct" => subcommands::distinct::run(args),
        "format" => subcommands::format_cmd::run(args),
        "gradient" => subcommands::gradient::run(args),
        "gray" => subcommands::gray::run(args),
        "lighten" => subcommands::transform::run_lighten(args),
        "list" => subcommands::list::run(args),
        "mix" => subcommands::mix::run(args),
        "paint" => subcommands::paint::run(args),
        "pick" => subcommands::pick::run(args),
        "random" => subcommands::random::run(args),
        "rotate" => subcommands::transform::run_rotate(args),
        "saturate" => subcommands::transform::run_saturate(args),
        "set" => subcommands::set::run(args),
        "sort-by" => subcommands::sort_by::run(args),
        "textcolor" => subcommands::textcolor::run(args),
        "to-gray" => subcommands::transform::run_to_gray(args),
        unknown => {
            let msg = format!(
                "error: unrecognized subcommand '{}'\n\n{}",
                unknown,
                help_strings::USAGE_MAIN
            );
            Err(AppError::Usage(msg))
        }
    }
}

