        "set" => subcommands::set::run(args),
        "sort-by" => subcommands::sort_by::run(args),
        "textcolor" => subcommands::textcolor::run(args),
        "to-gray" => subcommands::transform::run_to_gray(args),
        unknown => {
            let msg = format!(
                "error: unrecognized subcommand '{}'\n\n{}",
                unknown,
                help_strings::USAGE_MAIN
            );
            Err(AppError::Usage(msg))
        }
    }
}

fn validate_color_mode(v: &str) -> Result<(), AppError> {
    match v {
        "24bit" | "8bit" | "off" | "auto" => Ok(()),
        _ => Err(AppError::Usage(format!(
            "error: invalid value '{}' for '--color-mode <mode>'\n  [possible values: 24bit, 8bit, off, auto]\n\nFor more information, try '--help'.",
            v
        ))),
    }
}

fn validate_color_picker(v: &str) -> Result<(), AppError> {
    match v {
        "gpick" | "xcolor" | "wcolor" | "grabc" | "colorpicker" | "chameleon"
        | "kcolorchooser" | "zenity" | "yad" | "hyprpicker" | "gdbus" => Ok(()),
        _ => Err(AppError::Usage(format!(
            "error: invalid value '{}' for '--color-picker <color-picker>'\n  [possible values: gpick, xcolor, wcolor, grabc, colorpicker, chameleon, kcolorchooser, zenity, yad, hyprpicker, gdbus]\n\nFor more information, try '--help'.",
            v
        ))),
    }
}

fn print_subcommand_help(_sub: &str, _long: bool) -> Result<(), AppError> {
    // Simplified: just print the main help
    print!("{}", help_strings::MAIN_HELP_LONG);
    Ok(())
}

/// Read all colors from the argument list and/or stdin.  This is the
/// common input logic used by most subcommands.  `colors` is the list
/// of raw strings that should be interpreted as colors.  If the list is
/// empty, colors are read line-by-line from stdin.  A '-' entry also
/// triggers a read from stdin (single color).
pub fn read_colors(colors: Vec<String>) -> Result<Vec<color::Color>, AppError> {
    let mut result = Vec::new();
    if colors.is_empty() {
        let mut buf = String::new();
        io::stdin().read_to_string(&mut buf).ok();
        for line in buf.lines() {
            let t = line.trim();
            if t.is_empty() {
                continue;
            }
            let c = parser::parse_color(t)
                .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", t)))?;
            result.push(c);
        }
        return Ok(result);
    }
    for s in colors {
        if s == "-" {
            let mut buf = String::new();
            io::stdin().read_to_string(&mut buf).ok();
            let t = buf.trim();
            let c = parser::parse_color(t)
                .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", t)))?;
            result.push(c);
        } else if s == "pick" {
            return Err(AppError::Parse(
                "Could not find any external color picker tool. See 'pastel pick --help' for more information.".into(),
            ));
        } else {
            let c = parser::parse_color(&s)
                .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", s)))?;
            result.push(c);
        }
    }
    Ok(result)
}

pub fn print_color_summary(c: &color::Color) {
    let s = format::format_hsl_compact(c);
    let mut out = io::stdout().lock();
    let _ = writeln!(out, "{}", s);
}
