pub fn run(args: Vec<String>) -> Result<(), AppError> {
    let (_opts, positional) = crate::subcommands::parse_subcommand_args(args, &[])?;
    if !positional.is_empty() {
        return Err(AppError::Usage(format!(
            "error: unexpected argument '{}' found\n\nUsage: executable colorcheck\n\nFor more information, try '--help'.",
            positional[0]
        )));
