    let c8 = [(52u8), (23u8), (17u8)];
    let c24 = [(73u8, 39u8, 50u8), (16u8, 51u8, 30u8), (29u8, 54u8, 90u8)];

    writeln!(out).ok();
    writeln!(out, "8-bit mode:").ok();
    writeln!(out, "{:30}", "").ok();
    for _ in 0..4 {
        let mut line = String::from("  ");
        for (i, v) in c8.iter().enumerate() {
            for _ in 0..8 {
                line.push_str(&format!("\u{1b}[38;5;{};48;5;{}m \u{1b}[0m", v, v));
            }
            if i != c8.len() - 1 {
                line.push_str("  ");
            }
        }
        writeln!(out, "{}", line).ok();
    }
    writeln!(out, "{:30}", "").ok();

    writeln!(out, "24-bit mode:").ok();
    writeln!(out, "{:30}", "").ok();
    for _ in 0..4 {
        let mut line = String::from("  ");
        for (i, (r, g, b)) in c24.iter().enumerate() {
            for _ in 0..8 {
                line.push_str(&format!(
