                ));
            }
            if i != c24.len() - 1 {
                line.push_str("  ");
            }
        }
        writeln!(out, "{}", line).ok();
    }
    writeln!(out, "{:30}", "").ok();

    writeln!(out, "If your terminal emulator supports 24-bit colors, you should see three square color panels in the lower row and the colors should look similar (but slightly different from) the colors in the top row panels.").ok();
    writeln!(out, "The panels in the lower row should look like squares that are filled with a uniform color (no stripes or other artifacts).").ok();
    writeln!(out).ok();
    writeln!(out, "You can also open https://github.com/sharkdp/pastel/blob/master/doc/colorcheck.md in a browser to compare how the output should look like.").ok();
    Ok(())
}
