//! Simple color transformation subcommands: complement, darken, lighten,
//! saturate, desaturate, rotate, to-gray.

use crate::color::Color;
use crate::{print_color_summary, read_colors, AppError};

pub fn run_complement(args: Vec<String>) -> Result<(), AppError> {
    let (_opts, positional) = crate::subcommands::parse_subcommand_args(args, &[])?;
    let colors = read_colors(positional)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla((h + 180.0) % 360.0, s, l, a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_darken(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <amount>\n\nUsage: executable darken <amount> [color]...".into(),
        ));
    }
    let amount_raw = args.remove(0);
    let amount: f64 = amount_raw
        .parse()
        .map_err(|_| AppError::Usage(format!("invalid value '{}' for '<amount>'", amount_raw)))?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, s, (l - amount).clamp(0.0, 1.0), a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_lighten(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <amount>\n\nUsage: executable lighten <amount> [color]...".into(),
        ));
    }
    let amount_raw = args.remove(0);
    let amount: f64 = amount_raw
        .parse()
        .map_err(|_| AppError::Usage(format!("invalid value '{}' for '<amount>'", amount_raw)))?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, s, (l + amount).clamp(0.0, 1.0), a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_saturate(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <amount>\n\nUsage: executable saturate <amount> [color]...".into(),
        ));
    }
    let amount_raw = args.remove(0);
    let amount: f64 = amount_raw
        .parse()
        .map_err(|_| AppError::Usage(format!("invalid value '{}' for '<amount>'", amount_raw)))?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, (s + amount).clamp(0.0, 1.0), l, a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_desaturate(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <amount>\n\nUsage: executable desaturate <amount> [color]...".into(),
        ));
    }
    let amount_raw = args.remove(0);
    let amount: f64 = amount_raw
        .parse()
        .map_err(|_| AppError::Usage(format!("invalid value '{}' for '<amount>'", amount_raw)))?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, (s - amount).clamp(0.0, 1.0), l, a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_rotate(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <degrees>\n\nUsage: executable rotate <degrees> [color]...".into(),
        ));
    }
    let degs_raw = args.remove(0);
    let degs: f64 = degs_raw
        .parse()
        .map_err(|_| AppError::Usage(format!("invalid value '{}' for '<degrees>'", degs_raw)))?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let mut nh = h + degs;
        nh = ((nh % 360.0) + 360.0) % 360.0;
        let out = Color::from_hsla(nh, s, l, a);
        print_color_summary(&out);
    }
    Ok(())
}

