//! Color-blindness simulation using the Vienot & Brettel transforms.

use crate::color::Color;
use crate::{print_color_summary, read_colors, AppError};

pub fn run(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <type>\n\nUsage: executable colorblind <type> [color]...".into(),
        ));
    }
    let ty = args.remove(0);
    match ty.as_str() {
        "prot" | "deuter" | "trit" => {}
        _ => {
            return Err(AppError::Usage(format!(
                "error: invalid value '{}' for '<type>'\n  [possible values: prot, deuter, trit]\n\nFor more information, try '--help'.",
                ty
            )));
        }
    }
    let colors = read_colors(args)?;
    for c in colors {
        let out = simulate(&c, &ty);
        print_color_summary(&out);
    }
    Ok(())
}

fn lin(u: f64) -> f64 {
    if u <= 0.04045 {
        u / 12.92
    } else {
        ((u + 0.055) / 1.055).powf(2.4)
    }
}
fn enc(u: f64) -> f64 {
    if u <= 0.0031308 {
        12.92 * u
    } else {
        1.055 * u.powf(1.0 / 2.4) - 0.055
    }
}

fn simulate(c: &Color, ty: &str) -> Color {
    // Linearize sRGB
    let r = lin(c.r);
    let g = lin(c.g);
    let b = lin(c.b);

    // sRGB -> LMS (Hunt-Pointer-Estevez approximation)
    let l = 17.8824 * r + 43.5161 * g + 4.11935 * b;
    let m = 3.45565 * r + 27.1554 * g + 3.86714 * b;
    let s = 0.0299566 * r + 0.184309 * g + 1.46709 * b;

    let (lp, mp, sp) = match ty {
        "prot" => (
            0.0 * l + 2.02344 * m + -2.52581 * s,
            m,
            s,
        ),
        "deuter" => (
            l,
            0.494207 * l + 0.0 * m + 1.24827 * s,
            s,
        ),
        "trit" => (
            l,
            m,
            -0.395913 * l + 0.801109 * m + 0.0 * s,
        ),
        _ => (l, m, s),
    };

    // LMS -> sRGB (linear)
    let nr = 0.0809444479 * lp + -0.130504409 * mp + 0.116721066 * sp;
    let ng = -0.0102485335 * lp + 0.0540193266 * mp + -0.113614708 * sp;
    let nb = -0.000365296938 * lp + -0.00412161469 * mp + 0.693511405 * sp;

    Color {
        r: enc(nr.clamp(0.0, 1.0)),
        g: enc(ng.clamp(0.0, 1.0)),
        b: enc(nb.clamp(0.0, 1.0)),
        alpha: c.alpha,
    }
}
