pub fn interpolate_hue(h1: f64, h2: f64, f: f64) -> f64 {
    // Circular interpolation: pick the shortest direction.
    let mut diff = h1 - h2;
    while diff > 180.0 {
        diff -= 360.0;
    }
    while diff < -180.0 {
        diff += 360.0;
    }
    let h = h2 + diff * f;
    ((h % 360.0) + 360.0) % 360.0
}
