//! `random` subcommand and a tiny random-number generator used by
//! several other subcommands.

use crate::color::Color;
use crate::{print_color_summary, AppError};

pub struct Rng {
    state: u64,
}

pub fn new_rng() -> Rng {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    Rng {
        state: nanos ^ 0x9E3779B97F4A7C15,
    }
}

impl Rng {
    pub fn next_u64(&mut self) -> u64 {
        // SplitMix64
        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15);
        let mut z = self.state;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);
        z ^ (z >> 31)
    }
    pub fn next_f64(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / ((1u64 << 53) as f64)
    }
}

pub fn run(args: Vec<String>) -> Result<(), AppError> {
    let mut strategy = "vivid".to_string();
    let mut count: usize = 10;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "-s" || a == "--strategy" {
            i += 1;
            if let Some(v) = args.get(i) {
                strategy = v.clone();
            }
        } else if let Some(v) = a.strip_prefix("--strategy=") {
            strategy = v.to_string();
        } else if a == "-n" || a == "--number" {
            i += 1;
            if let Some(v) = args.get(i) {
                count = v.parse().map_err(|_| {
                    AppError::Usage(format!("invalid value '{}' for '<count>'", v))
                })?;
            }
        } else if let Some(v) = a.strip_prefix("--number=") {
            count = v.parse().map_err(|_| {
                AppError::Usage(format!("invalid value '{}' for '<count>'", v))
            })?;
        } else {
            return Err(AppError::Usage(format!(
                "error: unexpected argument '{}' found",
                a
            )));
        }
        i += 1;
    }
    let mut rng = new_rng();
    for _ in 0..count {
        let c = generate(&mut rng, &strategy);
        print_color_summary(&c);
    }
    Ok(())
}

fn generate(rng: &mut Rng, strategy: &str) -> Color {
    match strategy {
        "vivid" => {
            let h = rng.next_f64() * 360.0;
