                r,
                g,
                b,
                alpha: 1.0,
            }
        }
        "gray" => {
            let v = rng.next_f64();
            Color {
                r: v,
                g: v,
                b: v,
                alpha: 1.0,
            }
        }
        "lch_hue" => {
            let h = rng.next_f64() * 360.0;
