//! `paint` subcommand – print colored text using ANSI escape sequences.

use crate::{parser, AppError};
use std::io::{Read, Write};

pub fn run(args: Vec<String>) -> Result<(), AppError> {
    let mut bg: Option<String> = None;
    let mut bold = false;
    let mut italic = false;
    let mut underline = false;
    let mut no_newline = false;
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-o" | "--on" => {
                i += 1;
                bg = args.get(i).cloned();
            }
            "-b" | "--bold" => bold = true,
            "-i" | "--italic" => italic = true,
            "-u" | "--underline" => underline = true,
            "-n" | "--no-newline" => no_newline = true,
            s if s.starts_with("--on=") => bg = Some(s[5..].to_string()),
            _ => positional.push(a.clone()),
        }
        i += 1;
    }
    if positional.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <color>\n\nUsage: executable paint [OPTIONS] <color> [text]...".into(),
        ));
    }
    let color_raw = positional.remove(0);
    let fg = if color_raw == "-" {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).ok();
        parser::parse_color(s.trim())
            .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", s.trim())))?
    } else {
        parser::parse_color(&color_raw)
            .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", color_raw)))?
    };
    let bg_color = if let Some(b) = bg {
        Some(
            parser::parse_color(&b)
                .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", b)))?,
        )
    } else {
        None
    };

    let text: String = if positional.is_empty() {
        let mut s = String::new();
        std::io::stdin().read_to_string(&mut s).ok();
        s
    } else {
        positional.join(" ")
    };

    // Output: when stdout is not a TTY and no color mode forcing, we print
    // plain text.  The pastel binary chooses 24-bit if stdout is a TTY
    // with COLORTERM=truecolor, otherwise 8-bit on TTY, otherwise off.
    // We approximate: output plain text when stdout is not a TTY.
    let should_color = is_stdout_tty() || std::env::var("PASTEL_FORCE_COLOR").is_ok();
    let mut out = std::io::stdout().lock();
    if should_color {
        let (r, g, b) = fg.to_rgb_u8();
        let mut buf = format!("\u{1b}[38;2;{};{};{}", r, g, b);
        if let Some(bgc) = bg_color {
            let (br, bg_, bb) = bgc.to_rgb_u8();
            buf.push_str(&format!(";48;2;{};{};{}", br, bg_, bb));
        }
        if bold {
            buf.push_str(";1");
        }
        if italic {
            buf.push_str(";3");
        }
        if underline {
            buf.push_str(";4");
        }
        buf.push('m');
        write!(out, "{}{}\u{1b}[0m", buf, text).ok();
    } else {
        write!(out, "{}", text).ok();
    }
    if !no_newline {
        writeln!(out).ok();
    }
    Ok(())
}

fn is_stdout_tty() -> bool {
    unsafe { libc_isatty(1) != 0 }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}

#[allow(non_snake_case)]
unsafe fn libc_isatty(fd: i32) -> i32 {
    isatty(fd)
}
EOF
