use crate::color::Color;
use crate::{print_color_summary, read_colors, AppError};
use std::cmp::Ordering;

pub fn run(args: Vec<String>) -> Result<(), AppError> {
    let mut reverse = false;
    let mut unique = false;
    let mut order = "hue".to_string();
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    let mut saw_order = false;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-r" | "--reverse" => reverse = true,
            "-u" | "--unique" => unique = true,
            _ => {
                if !saw_order
                    && matches!(
                        a.as_str(),
                        "brightness" | "luminance" | "hue" | "chroma" | "random"
                    )
                {
                    order = a.clone();
                    saw_order = true;
                } else {
                    positional.push(a.clone());
                }
            }
        }
        i += 1;
    }

    let colors = read_colors(positional)?;
    let mut pairs: Vec<Color> = colors;

    match order.as_str() {
        "brightness" => pairs.sort_by(|a, b| cmp_f64(a.brightness(), b.brightness())),
        "luminance" => pairs.sort_by(|a, b| cmp_f64(a.luminance(), b.luminance())),
        "hue" => pairs.sort_by(|a, b| {
            let (_, _, h1, _) = a.to_lcha();
            let (_, _, h2, _) = b.to_lcha();
            cmp_f64(h1, h2)
        }),
        "chroma" => pairs.sort_by(|a, b| {
            let (_, c1, _, _) = a.to_lcha();
            let (_, c2, _, _) = b.to_lcha();
            cmp_f64(c1, c2)
        }),
        "random" => {
            let mut rng = crate::subcommands::random::new_rng();
            let n = pairs.len();
            for i in (1..n).rev() {
                let j = (rng.next_u64() as usize) % (i + 1);
                pairs.swap(i, j);
            }
        }
        _ => {
            return Err(AppError::Usage(format!(
                "error: invalid value '{}' for '<sort-order>'\n  [possible values: brightness, luminance, hue, chroma, random]\n\nFor more information, try '--help'.",
                order
            )));
        }
    }

    if reverse {
        pairs.reverse();
    }

    if unique {
        let mut seen = Vec::new();
        let mut dedup = Vec::new();
        for c in pairs {
            let key = c.to_rgb_u8();
            if !seen.contains(&key) {
                seen.push(key);
                dedup.push(c);
            }
        }
        pairs = dedup;
    }

    for c in pairs {
        print_color_summary(&c);
    }
    Ok(())
}

fn cmp_f64(a: f64, b: f64) -> Ordering {
    a.partial_cmp(&b).unwrap_or(Ordering::Equal)
}
