use crate::color::Color;
use crate::{print_color_summary, AppError};

pub fn run(args: Vec<String>) -> Result<(), AppError> {
    let mut count: usize = 10;
    let mut colorspace = "Lab".to_string();
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "-n" || a == "--number" {
            i += 1;
            if let Some(v) = args.get(i) {
                count = v.parse().map_err(|_| {
                    AppError::Usage(format!("invalid value '{}' for '<count>'", v))
                })?;
            }
        } else if let Some(v) = a.strip_prefix("--number=") {
            count = v
                .parse()
                .map_err(|_| AppError::Usage(format!("invalid value '{}' for '<count>'", v)))?;
        } else if a == "-s" || a == "--colorspace" {
            i += 1;
            if let Some(v) = args.get(i) {
                colorspace = v.clone();
            }
        } else if let Some(v) = a.strip_prefix("--colorspace=") {
            colorspace = v.to_string();
        } else {
            positional.push(a.clone());
        }
        i += 1;
    }
    if !["Lab", "LCh", "RGB", "HSL", "OkLab"].contains(&colorspace.as_str()) {
        return Err(AppError::Usage(format!(
            "error: invalid value '{}' for '--colorspace <name>'\n  [possible values: Lab, LCh, RGB, HSL, OkLab]\n\nFor more information, try '--help'.",
            colorspace
        )));
    }
    if positional.len() < 2 {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <color>...\n\nUsage: executable gradient [OPTIONS] <color>...".into(),
        ));
    }
    let mut stops: Vec<Color> = Vec::new();
    for s in positional {
        let c = crate::parser::parse_color(&s)
            .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", s)))?;
        stops.push(c);
    }
    let mut result: Vec<Color> = Vec::with_capacity(count);
    if count == 0 {
        return Ok(());
    }
    if count == 1 {
        result.push(stops[0]);
    } else {
        for i in 0..count {
            let t = i as f64 / (count - 1) as f64;
            // Find segment
            let segs = stops.len() - 1;
            let scaled = t * segs as f64;
            let seg = (scaled.floor() as usize).min(segs - 1);
            let local = scaled - seg as f64;
            let c = interpolate(&stops[seg], &stops[seg + 1], local, &colorspace);
            result.push(c);
        }
    }
    for c in result {
        print_color_summary(&c);
    }
    Ok(())
}

fn interpolate(a: &Color, b: &Color, t: f64, space: &str) -> Color {
    let f = 1.0 - t;
    match space {
        "RGB" => Color {
            r: a.r * f + b.r * t,
            g: a.g * f + b.g * t,
            b: a.b * f + b.b * t,
            alpha: a.alpha * f + b.alpha * t,
        },
        "HSL" => {
            let (h1, s1, l1, a1) = a.to_hsla();
            let (h2, s2, l2, a2) = b.to_hsla();
            let h = crate::subcommands::mix::interpolate_hue(h2, h1, f);
            Color::from_hsla(h, s1 * f + s2 * t, l1 * f + l2 * t, a1 * f + a2 * t)
        }
        "Lab" => {
            let (l1, aa1, bb1, a1) = a.to_laba();
            let (l2, aa2, bb2, a2) = b.to_laba();
            Color::from_laba(l1 * f + l2 * t, aa1 * f + aa2 * t, bb1 * f + bb2 * t, a1 * f + a2 * t)
        }
        "LCh" => {
            let (l1, c1, h1, a1) = a.to_lcha();
            let (l2, c2, h2, a2) = b.to_lcha();
            let h = crate::subcommands::mix::interpolate_hue(h2, h1, f);
            Color::from_lcha(l1 * f + l2 * t, c1 * f + c2 * t, h, a1 * f + a2 * t)
        }
        "OkLab" => {
            let (l1, aa1, bb1, a1) = a.to_oklaba();
            let (l2, aa2, bb2, a2) = b.to_oklaba();
            Color::from_oklaba(l1 * f + l2 * t, aa1 * f + aa2 * t, bb1 * f + bb2 * t, a1 * f + a2 * t)
        }
        _ => *a,
    }
}
