use crate::AppError;

/// Very small helper to split args into (options-we-don't-care-about, positional).
/// Currently this just returns (empty, args) since most subcommands don't have
/// their own options beyond `-h/--help` (which is filtered out earlier).
pub fn parse_subcommand_args(
    args: Vec<String>,
    known_flags: &[&str],
) -> Result<(Vec<String>, Vec<String>), AppError> {
    let mut options = Vec::new();
    let mut positional = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if known_flags.contains(&a.as_str()) {
            options.push(a.clone());
            i += 1;
            continue;
        }
        if a == "-h" || a == "--help" {
            // Subcommand help is handled by the caller.
            return Err(AppError::Exit(0));
        }
        positional.push(a.clone());
        i += 1;
    }
    Ok((options, positional))
}
