pub fn ansi_256_to_rgb(idx: u8) -> (u8, u8, u8) {
    match idx {
        0 => (0, 0, 0),
        1 => (128, 0, 0),
        2 => (0, 128, 0),
        3 => (128, 128, 0),
        4 => (0, 0, 128),
        5 => (128, 0, 128),
        6 => (0, 128, 128),
        7 => (192, 192, 192),
        8 => (128, 128, 128),
        9 => (255, 0, 0),
        10 => (0, 255, 0),
        11 => (255, 255, 0),
        12 => (0, 0, 255),
        13 => (255, 0, 255),
        14 => (0, 255, 255),
        15 => (255, 255, 255),
        16..=231 => {
            let v = idx - 16;
            let r = v / 36;
            let g = (v / 6) % 6;
            let b = v % 6;
            let to_6 = |c: u8| -> u8 {
                if c == 0 {
                    0
                } else {
                    55 + 40 * c
                }
            };
            (to_6(r), to_6(g), to_6(b))
        }
        232..=255 => {
            let v = idx - 232;
            let g = 8 + 10 * v;
            (g, g, g)
        }
    }
}
