//! Simple color transformation subcommands.

use crate::color::Color;
use crate::{print_color_summary, read_colors, AppError};

pub fn run_complement(args: Vec<String>) -> Result<(), AppError> {
    let (_opts, positional) = crate::subcommands::parse_subcommand_args(args, &[])?;
    let colors = read_colors(positional)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla((h + 180.0) % 360.0, s, l, a);
        print_color_summary(&out);
    }
    Ok(())
}

fn require_amount(args: &mut Vec<String>, name: &str, usage_hint: &str) -> Result<f64, AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(format!(
            "error: the following required arguments were not provided:\n  <{}>\n\nUsage: executable {}",
            name, usage_hint
        )));
    }
    let raw = args.remove(0);
    raw.parse().map_err(|_| {
        AppError::Usage(format!("invalid value '{}' for '<{}>'", raw, name))
    })
}

pub fn run_darken(mut args: Vec<String>) -> Result<(), AppError> {
    let amount = require_amount(&mut args, "amount", "darken <amount> [color]...")?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, s, (l - amount).clamp(0.0, 1.0), a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_lighten(mut args: Vec<String>) -> Result<(), AppError> {
    let amount = require_amount(&mut args, "amount", "lighten <amount> [color]...")?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, s, (l + amount).clamp(0.0, 1.0), a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_saturate(mut args: Vec<String>) -> Result<(), AppError> {
    let amount = require_amount(&mut args, "amount", "saturate <amount> [color]...")?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, (s + amount).clamp(0.0, 1.0), l, a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_desaturate(mut args: Vec<String>) -> Result<(), AppError> {
    let amount = require_amount(&mut args, "amount", "desaturate <amount> [color]...")?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let out = Color::from_hsla(h, (s - amount).clamp(0.0, 1.0), l, a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_rotate(mut args: Vec<String>) -> Result<(), AppError> {
    let degs = require_amount(&mut args, "degrees", "rotate <degrees> [color]...")?;
    let colors = read_colors(args)?;
    for c in colors {
        let (h, s, l, a) = c.to_hsla();
        let mut nh = h + degs;
        nh = ((nh % 360.0) + 360.0) % 360.0;
        let out = Color::from_hsla(nh, s, l, a);
        print_color_summary(&out);
    }
    Ok(())
}

pub fn run_to_gray(args: Vec<String>) -> Result<(), AppError> {
    let (_opts, positional) = crate::subcommands::parse_subcommand_args(args, &[])?;
    let colors = read_colors(positional)?;
    for c in colors {
        let y = c.luminance();
        // Encode luminance to sRGB, quantize to u8, then construct color.
        let v = srgb_encode(y);
        let u = (v * 255.0).round().clamp(0.0, 255.0) as u8;
        let (h, _, _, _) = c.to_hsla();
        let fv = u as f64 / 255.0;
        let out = Color {
            r: fv,
            g: fv,
            b: fv,
            alpha: c.alpha,
            hue_hint: Some(h),
        };
        print_color_summary(&out);
    }
    Ok(())
}

fn srgb_encode(u: f64) -> f64 {
    if u <= 0.0031308 {
        12.92 * u
    } else {
        1.055 * u.powf(1.0 / 2.4) - 0.055
    }
}
