                l1 * f + l2 * (1.0 - f),
                aa1 * f + aa2 * (1.0 - f),
                bb1 * f + bb2 * (1.0 - f),
                a1 * f + a2 * (1.0 - f),
            )
        }
        _ => unreachable!(),
    }
}

pub fn interpolate_hue(h1: f64, h2: f64, f: f64) -> f64 {
    // Circular interpolation: take the shortest direction.
    let mut diff = h2 - h1;
    while diff > 180.0 {
        diff -= 360.0;
    }
    while diff < -180.0 {
        diff += 360.0;
    }
    let h = h1 + diff * f;
    ((h % 360.0) + 360.0) % 360.0
}
