mod args;
mod color;
mod format;
mod help_strings;
mod named;
mod parser;
mod subcommands;

use std::io::{self, Read, Write};
use std::process::ExitCode;
use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum ColorMode {
    Auto,
    TwentyFour,
    Eight,
    Off,
}

static COLOR_MODE: OnceLock<ColorMode> = OnceLock::new();

pub fn color_mode() -> ColorMode {
    *COLOR_MODE.get().unwrap_or(&ColorMode::Auto)
}

/// Returns the effective color mode for *this* stream (stdout).
/// `Auto` is resolved to `TwentyFour`, `Eight`, or `Off` based on the
/// environment and whether stdout is a TTY.
pub fn effective_color_mode() -> ColorMode {
    match color_mode() {
        ColorMode::Auto => {
            if !is_stdout_tty() {
                ColorMode::Off
            } else if matches!(
                std::env::var("COLORTERM").as_deref(),
                Ok("truecolor") | Ok("24bit")
            ) {
                ColorMode::TwentyFour
            } else {
                ColorMode::Eight
            }
        }
        m => m,
    }
}

pub fn is_stdout_tty() -> bool {
    unsafe { isatty(1) != 0 }
}

extern "C" {
    fn isatty(fd: i32) -> i32;
}

fn main() -> ExitCode {
    let raw: Vec<String> = std::env::args().skip(1).collect();
    match run(raw) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => match e {
            AppError::Exit(code) => ExitCode::from(code),
            AppError::Parse(msg) => {
                eprintln!("[pastel error]: {}", msg);
