pub fn ansi_color_wrap(text: &str, bg: &color::Color) -> String {
    let mode = effective_color_mode();
    match mode {
        ColorMode::Off => text.to_string(),
        ColorMode::TwentyFour => {
            let (br, bg_, bb) = bg.to_rgb_u8();
            let fg = readable_fg(bg);
            let (fr, fg_, fb) = fg.to_rgb_u8();
            format!(
                "\u{1b}[38;2;{};{};{};48;2;{};{};{}m{}\u{1b}[0m",
                fr, fg_, fb, br, bg_, bb, text
            )
        }
        ColorMode::Eight => {
            let bgcode = bg.to_ansi_8bit();
            let fg = readable_fg(bg);
            let fgcode = fg.to_ansi_8bit();
            format!("\u{1b}[38;5;{};48;5;{}m{}\u{1b}[0m", fgcode, bgcode, text)
        }
        ColorMode::Auto => unreachable!(),
    }
}

fn readable_fg(bg: &color::Color) -> color::Color {
    let l = bg.luminance();
    if l > 0.179 {
        color::Color::from_rgb_u8(0, 0, 0)
    } else {
        color::Color::from_rgb_u8(255, 255, 255)
    }
}
