# This is the core change
cat > /workspace/src/color.rs <<'EOF'
//! Core color type and conversion routines.

/// Normalize a hue value so it lies in [0, 360].  Exactly `360.0`
/// is preserved (pastel keeps that value rather than wrapping it to 0).
pub fn normalize_hue(h: f64) -> f64 {
    if h == 360.0 {
        360.0
    } else {
        ((h % 360.0) + 360.0) % 360.0
    }
}

/// A color is stored internally as (hue, saturation, lightness, alpha).
/// RGB values are computed on demand from the HSL triple.  This matches
/// pastel's behaviour where HSL values set via `hsl(...)` round-trip
/// exactly and colors constructed from RGB go through u8 quantization
/// before being stored.
#[derive(Clone, Copy, Debug)]
pub struct Color {
    pub h: f64,
    pub s: f64,
    pub l: f64,
    pub alpha: f64,
}

impl Color {
    pub fn from_hsla(h: f64, s: f64, l: f64, alpha: f64) -> Color {
        Color {
            h: normalize_hue(h),
            s: s.clamp(0.0, 1.0),
            l: l.clamp(0.0, 1.0),
            alpha: alpha.clamp(0.0, 1.0),
        }
    }

    pub fn to_hsla(&self) -> (f64, f64, f64, f64) {
        (self.h, self.s, self.l, self.alpha)
    }

    // === Conversions to/from RGB ===

    /// Raw RGB as floats in 0..1, without u8 quantization.
    pub fn to_rgb_f(&self) -> (f64, f64, f64) {
        hsl_to_rgb(self.h, self.s, self.l)
    }

    pub fn to_rgb_u8(&self) -> (u8, u8, u8) {
        let (r, g, b) = self.to_rgb_f();
        (u8_round(r), u8_round(g), u8_round(b))
    }

    pub fn alpha_u8(&self) -> u8 {
        u8_round(self.alpha)
    }

    /// Construct a color from floating-point RGB.  `quantize` controls
    /// whether the RGB values are first rounded to u8 (matching how
    /// pastel handles RGB-like inputs).
    pub fn from_rgba_quantized(r: f64, g: f64, b: f64, alpha: f64) -> Color {
        let r = u8_round(r) as f64 / 255.0;
        let g = u8_round(g) as f64 / 255.0;
        let b = u8_round(b) as f64 / 255.0;
        Self::from_rgba_float(r, g, b, alpha)
    }

    pub fn from_rgba_float(r: f64, g: f64, b: f64, alpha: f64) -> Color {
        let r = r.clamp(0.0, 1.0);
        let g = g.clamp(0.0, 1.0);
        let b = b.clamp(0.0, 1.0);
        let (h, s, l) = rgb_to_hsl(r, g, b);
        Color {
            h,
            s,
            l,
            alpha: alpha.clamp(0.0, 1.0),
        }
    }

    pub fn from_rgb_u8(r: u8, g: u8, b: u8) -> Color {
        Self::from_rgba_float(r as f64 / 255.0, g as f64 / 255.0, b as f64 / 255.0, 1.0)
    }

    // === HSV ===
    pub fn to_hsva(&self) -> (f64, f64, f64, f64) {
        let (r, g, b) = self.to_rgb_f();
        let (h, s, v) = rgb_to_hsv(r, g, b, self.h);
        (h, s, v, self.alpha)
    }

    pub fn from_hsva(h: f64, s: f64, v: f64, alpha: f64) -> Color {
        let (r, g, b) = hsv_to_rgb(h, s, v);
        let (_hh, ss, ll) = rgb_to_hsl(r, g, b);
        Color {
            h: normalize_hue(h),
            s: ss,
            l: ll,
            alpha: alpha.clamp(0.0, 1.0),
        }
    }

    // === Lab / LCh / OkLab / OkLCh ===
    pub fn to_laba(&self) -> (f64, f64, f64, f64) {
        let (r, g, b) = self.to_rgb_f();
        let (x, y, z) = rgb_to_xyz(r, g, b);
        let (l, a, bb) = xyz_to_lab(x, y, z);
        (l, a, bb, self.alpha)
    }

    pub fn from_laba(l: f64, a: f64, b: f64, alpha: f64) -> Color {
        let (x, y, z) = lab_to_xyz(l, a, b);
        let (rr, gg, bb) = xyz_to_rgb(x, y, z);
        Color::from_rgba_quantized(rr * 255.0, gg * 255.0, bb * 255.0, alpha)
    }

    pub fn to_lcha(&self) -> (f64, f64, f64, f64) {
        let (l, a, b, alpha) = self.to_laba();
        let c = (a * a + b * b).sqrt();
        let mut h = b.atan2(a).to_degrees();
        if h < 0.0 {
            h += 360.0;
        }
        (l, c, h, alpha)
    }

    pub fn from_lcha(l: f64, c: f64, h: f64, alpha: f64) -> Color {
        let a = c * h.to_radians().cos();
        let b = c * h.to_radians().sin();
        Self::from_laba(l, a, b, alpha)
    }

