    }

    pub fn to_cmyk(&self) -> (f64, f64, f64, f64) {
        let (r, g, b) = self.to_rgb_f();
        let k = 1.0 - r.max(g).max(b);
        if k >= 1.0 - 1e-12 {
            (0.0, 0.0, 0.0, 1.0)
        } else {
            let c = (1.0 - r - k) / (1.0 - k);
            let m = (1.0 - g - k) / (1.0 - k);
            let y = (1.0 - b - k) / (1.0 - k);
