//! Core color type and conversion routines.

/// Normalize a hue value so it lies in [0, 360].  Exactly `360.0`
/// is preserved (pastel keeps that value rather than wrapping it to 0).
pub fn normalize_hue(h: f64) -> f64 {
    if h == 360.0 {
        360.0
    } else {
        ((h % 360.0) + 360.0) % 360.0
    }
}

/// A color is stored internally as (hue, saturation, lightness, alpha).
/// RGB values are computed on demand from the HSL triple.  This matches
/// pastel's behaviour where HSL values set via `hsl(...)` round-trip
/// exactly and colors constructed from RGB go through u8 quantization
/// before being stored.
#[derive(Clone, Copy, Debug)]
pub struct Color {
    pub h: f64,
    pub s: f64,
    pub l: f64,
    pub alpha: f64,
}

impl Color {
    pub fn from_hsla(h: f64, s: f64, l: f64, alpha: f64) -> Color {
        Color {
            h: normalize_hue(h),
            s: s.clamp(0.0, 1.0),
            l: l.clamp(0.0, 1.0),
