            let l: f64 = parts[0].parse().ok()?;
            let c: f64 = parts[1].parse().ok()?;
            let h = parse_hue(parts[2])?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color::from_lcha(l, c, h, alpha))
        }
        "oklab" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            let l: f64 = parts[0].parse().ok()?;
            let a: f64 = parts[1].parse().ok()?;
            let b: f64 = parts[2].parse().ok()?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color::from_oklaba(l, a, b, alpha))
        }
        "oklch" => {
            if parts.len() != 3 && parts.len() != 4 {
                return None;
            }
            let l: f64 = parts[0].parse().ok()?;
            let c: f64 = parts[1].parse().ok()?;
            let h = parse_hue(parts[2])?;
            let alpha = if parts.len() == 4 {
                parse_alpha(parts[3])?
            } else {
                1.0
            };
            Some(Color::from_oklcha(l, c, h, alpha))
        }
        _ => None,
    }
}

fn parse_csv(s: &str) -> Option<Color> {
    let parts: Vec<&str> = s.split(',').map(|p| p.trim()).collect();
    if parts.len() != 3 {
        return None;
    }
    let r: f64 = parts[0].parse().ok()?;
    let g: f64 = parts[1].parse().ok()?;
    let b: f64 = parts[2].parse().ok()?;
    Some(Color::from_rgba_quantized(r, g, b, 1.0))
}

fn parse_num_or_percent(s: &str, max: f64, is_pct: bool) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        if !is_pct {
            return None;
        }
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0) * max)
    } else {
        if is_pct {
            return None;
        }
        let v: f64 = s.parse().ok()?;
        Some(v)
    }
}

fn parse_percentage(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some(v / 100.0)
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v / 100.0)
    }
}

fn parse_alpha(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0).clamp(0.0, 1.0))
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v.clamp(0.0, 1.0))
    }
}

fn parse_hue(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix("deg") {
        rest.trim().parse().ok()
    } else if let Some(rest) = s.strip_suffix("rad") {
        let v: f64 = rest.trim().parse().ok()?;
        Some(v.to_degrees())
    } else {
        s.parse().ok()
    }
}

fn parse_gray_amount(s: &str) -> Option<f64> {
    if let Some(rest) = s.strip_suffix('%') {
        let v: f64 = rest.trim().parse().ok()?;
        Some((v / 100.0).clamp(0.0, 1.0))
    } else {
        let v: f64 = s.parse().ok()?;
        Some(v.clamp(0.0, 1.0))
    }
}
