pub fn format_hex(c: &Color) -> String {
    let (r, g, b) = c.to_rgb_u8();
    let a = c.alpha_u8();
    if a == 255 {
        format!("#{:02x}{:02x}{:02x}", r, g, b)
    } else {
        format!("#{:02x}{:02x}{:02x}{:02x}", r, g, b, a)
    }
}

