    let (r, g, b) = c.to_rgb_u8();
    if !has_alpha(c) {
        format!("rgb({}, {}, {})", r, g, b)
    } else {
        format!("rgba({}, {}, {}, {})", r, g, b, format_alpha(c.alpha))
    }
}

