    let mut best_d = f64::INFINITY;
    for (n, nr, ng, nb) in NAMED_COLORS {
        if matches!(
            *n,
            "grey"
                | "darkgrey"
                | "lightgrey"
                | "darkslategrey"
                | "lightslategrey"
                | "dimgrey"
                | "slategrey"
                | "cyan"
                | "magenta"
