        let nc = Color::from_rgb_u8(*nr, *ng, *nb);
        let (ln, an, bn, _) = nc.to_oklaba();
        let dl = lc - ln;
        let da = ac - an;
        let db = bc - bn;
        let d = dl * dl + da * da + db * db;
        if d < best_d {
            best_d = d;
            best = n;
        }
    }
    best.to_string()
