pub fn run(mut args: Vec<String>) -> Result<(), AppError> {
    if args.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <type>\n\nUsage: executable colorblind <type> [color]...".into(),
        ));
    }
    let ty = args.remove(0);
    match ty.as_str() {
        "prot" | "deuter" | "trit" => {}
        _ => {
            return Err(AppError::Usage(format!(
                "error: invalid value '{}' for '<type>'\n  [possible values: prot, deuter, trit]\n\nFor more information, try '--help'.",
                ty
            )));
        }
    }
    let colors = read_colors(args)?;
    for c in colors {
        let out = simulate(&c, &ty);
        print_color_summary(&out);
    }
    Ok(())
