    let (nr, ng, nb) = apply(m, r, g, b);
    Color::from_rgba_quantized(
        enc(nr.clamp(0.0, 1.0)) * 255.0,
        enc(ng.clamp(0.0, 1.0)) * 255.0,
        enc(nb.clamp(0.0, 1.0)) * 255.0,
        c.alpha,
    )
}
