        } else if a == "-f" || a == "--fraction" {
            i += 1;
            if let Some(v) = args.get(i) {
                fraction = v.parse().map_err(|_| {
                    AppError::Usage(format!("invalid value '{}' for '<fraction>'", v))
                })?;
            }
            i += 1;
        } else if let Some(v) = a.strip_prefix("--fraction=") {
            fraction = v.parse().map_err(|_| {
                AppError::Usage(format!("invalid value '{}' for '<fraction>'", v))
            })?;
            i += 1;
        } else {
            positional.push(a.clone());
            i += 1;
        }
    }
    if !["Lab", "LCh", "RGB", "HSL", "OkLab"].contains(&colorspace.as_str()) {
        return Err(AppError::Usage(format!(
            "error: invalid value '{}' for '--colorspace <name>'\n  [possible values: Lab, LCh, RGB, HSL, OkLab]\n\nFor more information, try '--help'.",
            colorspace
        )));
    }
    if positional.is_empty() {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <color>\n\nUsage: executable mix [OPTIONS] <color> [color]...".into(),
        ));
    }
    let base_raw = positional.remove(0);
    let base = crate::parser::parse_color(&base_raw)
        .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", base_raw)))?;
    let others = crate::read_colors(positional)?;
    for o in others {
        let mixed = mix_color(&base, &o, &colorspace, fraction);
        print_color_summary(&mixed);
    }
    Ok(())
}

fn mix_color(base: &Color, other: &Color, space: &str, f: f64) -> Color {
    let f = f.clamp(0.0, 1.0);
    let g = 1.0 - f;
    match space {
        "RGB" => {
            let (b_r, b_g, b_b) = base.to_rgb_f();
            let (o_r, o_g, o_b) = other.to_rgb_f();
            Color::from_rgba_quantized(
                (b_r * f + o_r * g) * 255.0,
                (b_g * f + o_g * g) * 255.0,
                (b_b * f + o_b * g) * 255.0,
                base.alpha * f + other.alpha * g,
            )
        }
        "HSL" => {
            let (h1, s1, l1, a1) = base.to_hsla();
            let (h2, s2, l2, a2) = other.to_hsla();
            let h = interpolate_hue(h2, h1, f);
            Color::from_hsla(h, s1 * f + s2 * g, l1 * f + l2 * g, a1 * f + a2 * g)
        }
        "LCh" => {
            let (l1, c1, h1, a1) = base.to_lcha();
            let (l2, c2, h2, a2) = other.to_lcha();
            let h = interpolate_hue(h2, h1, f);
            Color::from_lcha(l1 * f + l2 * g, c1 * f + c2 * g, h, a1 * f + a2 * g)
        }
        "Lab" => {
            let (l1, aa1, bb1, a1) = base.to_laba();
            let (l2, aa2, bb2, a2) = other.to_laba();
            Color::from_laba(
                l1 * f + l2 * g,
                aa1 * f + aa2 * g,
                bb1 * f + bb2 * g,
                a1 * f + a2 * g,
            )
        }
        "OkLab" => {
            let (l1, aa1, bb1, a1) = base.to_oklaba();
            let (l2, aa2, bb2, a2) = other.to_oklaba();
            Color::from_oklaba(
                l1 * f + l2 * g,
                aa1 * f + aa2 * g,
                bb1 * f + bb2 * g,
                a1 * f + a2 * g,
            )
        }
        _ => unreachable!(),
    }
}

pub fn interpolate_hue(h1: f64, h2: f64, f: f64) -> f64 {
    let mut diff = h2 - h1;
    while diff > 180.0 {
        diff -= 360.0;
    }
    while diff < -180.0 {
        diff += 360.0;
    }
    let h = h1 + diff * f;
    crate::color::normalize_hue(h)
}
