            colorspace
        )));
    }
    if positional.len() < 2 {
        return Err(AppError::Usage(
            "error: the following required arguments were not provided:\n  <color>...\n\nUsage: executable gradient [OPTIONS] <color>...".into(),
        ));
    }
    let mut stops: Vec<Color> = Vec::new();
    for s in positional {
        let c = crate::parser::parse_color(&s)
            .ok_or_else(|| AppError::Parse(format!("Could not parse color '{}'", s)))?;
        stops.push(c);
    }
    if count == 0 {
        return Ok(());
    }
