    let segs = stops.len() - 1;
    for i in 0..count {
        let t = i as f64 / (count - 1) as f64;
        let scaled = t * segs as f64;
        let seg = (scaled.floor() as usize).min(segs - 1);
        let local = scaled - seg as f64;
        let c = interpolate(&stops[seg], &stops[seg + 1], local, &colorspace);
        print_color_summary(&c);
