            let (l2, aa2, bb2, a2) = b.to_oklaba();
            Color::from_oklaba(l1 * f + l2 * t, aa1 * f + aa2 * t, bb1 * f + bb2 * t, a1 * f + a2 * t)
        }
        _ => *a,
    }
}
