        if a == "-s" || a == "--strategy" {
            i += 1;
            if let Some(v) = args.get(i) {
                strategy = v.clone();
            }
        } else if let Some(v) = a.strip_prefix("--strategy=") {
            strategy = v.to_string();
        } else if a == "-n" || a == "--number" {
            i += 1;
            if let Some(v) = args.get(i) {
                count = v.parse().map_err(|_| {
                    AppError::Usage(format!("invalid value '{}' for '<count>'", v))
                })?;
            }
        } else if let Some(v) = a.strip_prefix("--number=") {
            count = v.parse().map_err(|_| AppError::Usage(format!("invalid value '{}' for '<count>'", v)))?;
        } else {
            return Err(AppError::Usage(format!("error: unexpected argument '{}' found", a)));
        }
        i += 1;
    }
    let mut rng = new_rng();
    for _ in 0..count {
        let c = generate(&mut rng, &strategy);
        print_color_summary(&c);
    }
    Ok(())
}

fn generate(rng: &mut Rng, strategy: &str) -> Color {
    match strategy {
        "vivid" => {
            let h = rng.next_f64() * 360.0;
            let s = 0.2 + rng.next_f64() * 0.8;
            let l = 0.3 + rng.next_f64() * 0.4;
            Color::from_hsla(h, s, l, 1.0)
        }
        "rgb" => {
            let r = rng.next_f64();
            let g = rng.next_f64();
            let b = rng.next_f64();
            Color::from_rgba_quantized(r * 255.0, g * 255.0, b * 255.0, 1.0)
        }
        "gray" => {
            let v = rng.next_f64();
            Color::from_rgba_quantized(v * 255.0, v * 255.0, v * 255.0, 1.0)
        }
        "lch_hue" => {
            let h = rng.next_f64() * 360.0;
            Color::from_lcha(65.0, 30.0, h, 1.0)
        }
        _ => {
            let h = rng.next_f64() * 360.0;
            Color::from_hsla(h, 0.5, 0.5, 1.0)
        }
    }
}
