    let mut diff = h2 - h1;
    while diff > 180.0 {
        diff -= 360.0;
    }
    while diff < -180.0 {
        diff += 360.0;
    }
    let h = h1 + diff * f;
    crate::color::normalize_hue(h)
}'''
new = '''pub fn interpolate_hue(h1: f64, h2: f64, f: f64) -> f64 {
    let mut diff = h2 - h1;
    while diff > 180.0 {
        diff -= 360.0;
    }
    while diff < -180.0 {
        diff += 360.0;
    }
    let h = h1 + diff * f;
    ((h % 360.0) + 360.0) % 360.0
}'''
