# Compute inverse manually using Gauss-Jordan
def inv(m):
    n = len(m)
    # Augment with identity
    a = [row[:] + [1.0 if i==j else 0.0 for j in range(n)] for i,row in enumerate(m)]
    for i in range(n):
        # Find pivot
        piv = i
        for k in range(i+1, n):
            if abs(a[k][i]) > abs(a[piv][i]):
                piv = k
        a[i], a[piv] = a[piv], a[i]
        p = a[i][i]
        for j in range(2*n):
            a[i][j] /= p
        for k in range(n):
            if k != i:
                f = a[k][i]
                for j in range(2*n):
                    a[k][j] -= f * a[i][j]
    return [row[n:] for row in a]

LMS_to_XYZ = inv([
